/// Checks if a given subtag is a known language subtag. Lowercases the input before checking.
pub fn is_language_subtag(subtag: &str) -> bool {
    lookup(LANGUAGE_SUBTAGS_ARRAY, &subtag.to_ascii_lowercase()).is_some()
}
/// Checks if a given language subtag is registered as private use. Lowercases the input before checking.
pub fn is_language_private_use(subtag: &str) -> bool {
    lookup(LANGUAGE_SUBTAGS_ARRAY, &subtag.to_ascii_lowercase())
        .is_some_and(|(_, is_private_use, _)| is_private_use)
}
/// Checks if a given language subtag is deprecated with a preferred value provided. Lowercases the input before checking.
pub fn is_deprecated_language_with_preferred_value(
    subtag: &str,
) -> Option<&'static str> {
    lookup(LANGUAGE_SUBTAGS_ARRAY, &subtag.to_ascii_lowercase())
        .and_then(|(_, _, preferred_value)| preferred_value)
}
